python3 -c "
import json, hashlib, glob, os
D='demos/doc-drift/corpus'
truth={'v01':'accurate','v02':'accurate','v03':'accurate','v04':'accurate','r01':'drifted','r02':'drifted','r03':'drifted','r04':'drifted','s01':'drifted','s02':'drifted','s03':'drifted','s04':'drifted','b01':'drifted','b02':'drifted','b03':'drifted','c01':'drifted','c02':'drifted','c03':'drifted','a01':'unknown','a02':'unknown'}
classes={'v':'valid-anchor','r':'reference-drift','s':'semantic-default','b':'behavior','c':'coverage','a':'ambiguous'}
cases=[]
for cid in sorted(truth):
    files=sorted(glob.glob(D+'/'+cid+'/**/*', recursive=True))
    files=[f for f in files if os.path.isfile(f)]
    rec={'case_id':cid,'class':classes[cid[0]],'truth':truth[cid],'files':[]}
    for f in files:
        b=open(f,'rb').read()
        rec['files'].append({'path':os.path.relpath(f,D),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
    cases.append(rec)
man={'schema':'jev.docdrift.corpus.v1','cases':cases,'counts':{k:sum(1 for c in cases if c['class']==k) for k in classes.values()}}
json.dump(man,open(D+'/../corpus.json','w'),indent=1)
print('cases:',len(cases),man['counts'])
"

